# Per-million token prices (as of late 2024 estimates)
# This fulfills the directive from dept_finance_ops
MODEL_PRICING = {
    "gpt-4o-mini": {"input": 0.15, "output": 0.60},
    "llama3": {"input": 0.0, "output": 0.0}, # Local model is a capital cost, not opex
    "claude-3-haiku-20240307": {"input": 0.25, "output": 1.25},
    "gemini/gemini-1.5-flash": {"input": 0.35, "output": 0.70},
}

class CostTracker:
    def __init__(self, budget: float):
        self.total_cost = 0.0
        self.budget = budget

    def log_and_check(self, model: str, input_tokens: int, output_tokens: int) -> float:
        """Calculates cost and returns it, updating total. Halts if over budget."""
        # Normalize model name for pricing lookup if it comes from litellm with a prefix
        if "/" in model:
            model_base_name = model.split('/')[-1]
        else:
            model_base_name = model

        # Handle specific model mappings if litellm provides a different string than our MODEL_PRICING keys
        # For example, litellm might return 'ollama/llama3' but our key is 'llama3'
        if model_base_name == "llama3":
            pricing_key = "llama3"
        elif "gpt-4o-mini" in model_base_name: # Handle potential variations like 'gpt-4o-mini-2024-05-13'
            pricing_key = "gpt-4o-mini"
        elif "claude-3-haiku" in model_base_name:
            pricing_key = "claude-3-haiku-20240307"
        elif "gemini-1.5-flash" in model_base_name:
            pricing_key = "gemini/gemini-1.5-flash"
        else:
            pricing_key = model_base_name # Fallback

        if pricing_key not in MODEL_PRICING:
            print(f"Warning: No pricing information for model '{model}' (looked for '{pricing_key}'). Cost not calculated.")
            return 0.0

        input_cost = (input_tokens / 1_000_000) * MODEL_PRICING[pricing_key]["input"]
        output_cost = (output_tokens / 1_000_000) * MODEL_PRICING[pricing_key]["output"]

        iteration_cost = input_cost + output_cost
        self.total_cost += iteration_cost

        if self.total_cost > self.budget:
            raise Exception(f"Budget exceeded! Total cost: ${self.total_cost:.6f} > Budget: ${self.budget:.6f}")

        return iteration_cost
